function qualityValue(value){return typeof value==='number'&&Number.isFinite(value)&&value>=0&&value<=100?Math.round(value):null}
function productRatingBadge(value,demo=false){const score=qualityValue(value);return `<span class="product-rating ${score===null?'unrated':score>=90?'excellent':score>=75?'good':'fair'}" title="${demo?'Демонстрационная оценка':'Оценка фермы по приёмке'}">${score===null?'◌ Без оценки':`★ ${score}<small>/100</small>`}${demo?'<em>Демо</em>':''}</span>`}
function productDate(date){return date?new Date(date).toLocaleDateString('ru-RU'):'Пока нет данных'}
function passportFact(label,value){return `<div><small>${esc(label)}</small><b>${esc(value??'Пока нет данных')}</b></div>`}
function productPassportHTML(d){const b=d.batch,score=qualityValue(d.rating?.score),assessment=d.assessments?.[0],works=d.works||[],days=d.cultivation?.starts_on&&b.harvested_on?Math.max(0,Math.round((Date.parse(b.harvested_on)-Date.parse(d.cultivation.starts_on))/86400000)):null,counts=[['💧','Поливы',['water']],['🌿','Подкормки',['feed','fertilize']],['🌾','Прополки',['weed']],['🪏','Подготовка',['prepare']]];return `<section class="product-passport"><header class="passport-cover"><span class="passport-produce" aria-hidden="true">${storageCropIcon(b.crop)}</span><div><small>${d.demo?'ДЕМОПАСПОРТ':'ПАСПОРТ УРОЖАЯ'}</small><h2>${esc(b.crop)}</h2><p>${esc(d.farm||'Урожай с наблюдением за выращиванием')}</p></div><div class="passport-rating-ring" style="--quality:${score??0}%"><div><strong>${score??'—'}</strong><small>${score===null?'нет оценки':'из 100'}</small></div></div></header>${d.demo?'<p class="passport-demo-note">Демонстрационный пример: урожай, оценка и история условные. Реальные покупки и доставка не выполняются.</p>':''}<div class="passport-section"><h3>Качество продукта</h3><p>${esc(d.rating?.reason||'Оценка фермы пока не подтверждена.')}</p>${(assessment?.breakdown||[]).map(x=>`<div class="passport-quality-line"><span>${esc(x.name)}<small>Вес ${x.weight}%</small></span><div><i style="width:${qualityValue(x.score)??0}%"></i></div><b>${qualityValue(x.score)??'—'}</b></div>${x.evidence?`<p class="passport-evidence">${esc(x.evidence)}</p>`:''}`).join('')||'<div class="passport-pending">◌ Подтверждённая оценка появится после приёмки фермы.</div>'}<small>Оценка от ${productDate(d.rating?.assessed_at)} · ${esc(d.rating?.version||'farm-observation-v1')}. Это оценка партии, а не лабораторное заключение.</small></div><div class="passport-section"><h3>Откуда урожай</h3><div class="passport-facts">${passportFact('Грядка',b.plot_id?'№'+b.plot_id:'Пока не указана')}${passportFact('Культура',d.cultivation?.crop||b.crop)}${passportFact('Посадка',productDate(d.cultivation?.starts_on))}${passportFact('Сбор',productDate(b.harvested_on))}${passportFact('Выращивание',days===null?'Пока нет данных':'Дней: '+days)}${passportFact('Собрано',b.received_grams===undefined?'Пока нет данных':storageKg(b.received_grams))}</div></div><div class="passport-section"><h3>Как заботились</h3><div class="passport-care-grid">${counts.map(([icon,label,codes])=>`<div><span>${icon}</span><b>${works.filter(w=>codes.includes(w.service_code)).length}</b><small>${label}</small></div>`).join('')}</div><p class="passport-evidence">Считаются подтверждённые работы, связанные с посадкой этой партии. Ноль означает, что записей нет.</p><details><summary>Дневник выращивания · записей: ${works.length}</summary>${works.map(w=>`<div class="passport-timeline-event"><b>${esc(w.title)}</b><small>${productDate(w.finished_at)}</small></div>`).join('')||'<p>Связанные работы ещё не добавлены.</p>'}</details></div><div class="passport-section"><h3>Хранение и остаток</h3><div class="passport-facts">${passportFact('Где хранится',b.storage_kind==='pantry'?'Кладовая':b.storage_kind==='fridge'?'Холодильник':'Ожидает размещения')}${passportFact('Срок хранения',productDate(b.expires_at))}${b.balance_grams!==undefined?passportFact('На складе',storageKg(b.balance_grams))+passportFact('В резерве',storageKg(b.reserved_grams||0))+passportFact('Доступно',storageKg(Math.max(0,Number(b.balance_grams)-Number(b.reserved_grams||0)))):''}${passportFact('Приёмка',b.verified?'Подтверждена':'Ожидается')}</div><p>${esc(b.storage_conditions||'Условия хранения ещё не записаны.')}</p></div>${d.evidence?.length?`<div class="passport-section"><h3>Фото и подтверждения</h3>${d.evidence.map(e=>`<p><b>${esc(e.kind)}</b> · ${productDate(e.created_at)}<br>${esc(e.description)}${e.url?`<br><a href="${esc(e.url)}" target="_blank" rel="noopener noreferrer">Открыть подтверждение</a>`:''}</p>`).join('')}</div>`:''}<details class="passport-section"><summary>Движение урожая · записей: ${(d.events||[]).length}</summary>${(d.events||[]).map(e=>`<p>${esc(({received:'Приход',reserve:'Резерв',release:'Освобождение резерва',ship:'Выдача',writeoff:'Списание'})[e.kind]||e.kind)} · ${storageKg(e.grams)} · ${productDate(e.created_at)}<br>${esc(e.reason)}</p>`).join('')||'<p>Доступных записей пока нет.</p>'}</details><footer class="passport-id">Партия ${esc(b.id)}${d.origin?.transfers?' · Передач: '+d.origin.transfers:''}</footer>${account?.role==='admin'&&!d.demo&&!d.public?`<button type="button" class="btn light" onclick="assessHarvest('${b.id}')">Подтвердить оценку по приёмке</button>`:''}</section>`}
showPassport=async function(id){try{const d=await api('passport',{id});modalForm('Паспорт продукта',productPassportHTML(d),()=>{})}catch(e){toast(e.message)}};
function samplePassport(batch,score){const now=new Date(),date=n=>new Date(now.getTime()-n*86400000).toISOString(),criteria=[['condition','Состояние урожая',40],['ripeness','Спелость',25],['handling','Хранение',20],['traceability','Происхождение',15]],works=[...Array.from({length:16},(_,i)=>({title:'Полив по плану',service_code:'water',finished_at:date(70-i*4)})),...Array.from({length:3},(_,i)=>({title:'Согласованная подкормка',service_code:'feed',finished_at:date(55-i*15)})),{title:'Подготовка почвы',service_code:'prepare',finished_at:date(75)},{title:'Прополка',service_code:'weed',finished_at:date(35)}];return {demo:true,batch:{...batch,verified:true,plot_id:7,harvested_on:date(2),received_grams:batch.balance_grams,expires_at:new Date(now.getTime()+4*86400000).toISOString(),storage_conditions:'Пример: условия подтверждены при приёмке демопартии.'},cultivation:{crop:batch.crop,starts_on:date(75)},farm:'Пример хозяйства после полугода игры',rating:{score,reason:'Демонстрационная оценка по четырём критериям.',version:'demo-observation-v1',assessed_at:date(1)},assessments:[{breakdown:criteria.map(([id,name,weight])=>({id,name,weight,score,evidence:'Условное подтверждение для демонстрации паспорта.'}))}],works,evidence:[],events:[{kind:'received',grams:batch.balance_grams,reason:'Тестовый сбор урожая',created_at:date(2)}]}}
const beforeRatedDemoBatches=demoStorageBatches;demoStorageBatches=function(){return beforeRatedDemoBatches().map((b,i)=>({...b,quality_score:[94,91,96,90,93,88,95,92,94,90,91,97][i]}))};
demoStoragePassport=function(id){const b=demoStorageBatches().find(x=>x.id===id);if(b)modalForm('Демопаспорт продукта',productPassportHTML(samplePassport(b,b.quality_score)),()=>{})};
const beforeRatedInteriorProduce=interiorProduce;interiorProduce=function(b){return beforeRatedInteriorProduce(b).replace('<span class="interior-tag">',`<span class="interior-tag">${productRatingBadge(b.quality_score,b.is_demo)}`)};
const beforeRatedStorageCrate=storageCrate;storageCrate=function(b){return beforeRatedStorageCrate(b).replace('<span class="crate-label">',`<span class="crate-label">${productRatingBadge(b.quality_score,b.is_demo)}`)};
function demoCatalogRating(p){return p.category==='Овощи'?88+[...p.id].reduce((n,x)=>n+x.charCodeAt(0),0)%10:null}
function showCatalogPassport(id){const p=demoCatalog.find(x=>x.id===id);if(!p)return;if(p.category==='Овощи'){const d=samplePassport({id:'catalog-demo-'+id,crop:p.name,storage_kind:'fridge',balance_grams:1000,reserved_grams:0},demoCatalogRating(p));modalForm('Демопаспорт продукта',productPassportHTML(d),()=>{});return}const detail=journeyData?.products?.find(x=>x.catalog_id===id);modalForm('Карточка товара',`<section class="product-passport"><header class="passport-cover"><span class="passport-produce">${storageCropIcon(p.name)}</span><div><small>ДЕМОТОВАР</small><h2>${esc(p.name)}</h2>${productRatingBadge(null)}</div></header><div class="passport-section"><h3>${p.price} демо-₽ / ${esc(p.unit)}</h3><p>${esc(detail?.description||marketDescription(p))}</p><p>Рейтинг урожая применяется к собранной партии. Для этого товара оценка пока не указана.</p>${detail?.variety?passportFact('Сорт',detail.variety):''}</div></section>`,()=>{})}
const beforePassportMarket=demoMarketPage;demoMarketPage=function(){const box=document.createElement('div');box.innerHTML=beforePassportMarket();const products=demoCatalog.filter(p=>(demoMarketFilter==='Все'||p.category===demoMarketFilter)&&p.name.toLowerCase().includes(demoMarketSearch.toLowerCase()));box.querySelectorAll('.grid>article').forEach((card,i)=>{const p=products[i];if(!p)return;card.classList.add('rated-market-card');const rating=document.createElement('button');rating.type='button';rating.className='market-passport-button';rating.setAttribute('onclick',`showCatalogPassport('${p.id}')`);rating.innerHTML=productRatingBadge(demoCatalogRating(p),p.category==='Овощи')+'<span>Паспорт продукта →</span>';card.querySelector('h3').insertAdjacentElement('afterend',rating);const photo=card.querySelector('.market-product-photo');if(photo){photo.setAttribute('role','button');photo.setAttribute('tabindex','0');photo.setAttribute('aria-label','Паспорт: '+p.name);photo.setAttribute('onclick',`showCatalogPassport('${p.id}')`);photo.setAttribute('onkeydown',`if(event.key==='Enter'||event.key===' '){event.preventDefault();showCatalogPassport('${p.id}')}`)}});
 const real=(lifeData?.listings||[]).filter(l=>!demoMarketSearch||l.crop.toLowerCase().includes(demoMarketSearch.toLowerCase()));if(real.length&&['Все','Овощи'].includes(demoMarketFilter)){const section=document.createElement('section');section.className='real-market-shelves';section.innerHTML=`<h2>Урожай со складов</h2><div class="grid">${real.map(l=>`<article class="panel rated-market-card"><button class="market-real-produce" onclick="showPassport('${l.batch_id}')" aria-label="Паспорт: ${esc(l.crop)}">${storageCropIcon(l.crop)}</button><h3>${esc(l.crop)}</h3><button class="market-passport-button" onclick="showPassport('${l.batch_id}')">${productRatingBadge(l.quality_score)}<span>Паспорт продукта →</span></button><p>${storageKg(l.grams)} · ${money(l.price_kopecks)} за лот</p>${l.owner_id!==account?.id?`<button class="btn" onclick="buyProduce('${l.id}')">Купить демосредствами</button>`:'<small>Ваш урожай</small>'}</article>`).join('')}</div>`;box.querySelector('.grid')?.before(section)}return box.innerHTML};
function decorateMarketLanguage(){const walker=document.createTreeWalker(document.querySelector('#app'),NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){if(!['SCRIPT','STYLE','TEXTAREA','INPUT'].includes(node.parentElement?.tagName))node.nodeValue=node.nodeValue.replace(/(?<![а-яё])маркет(а|е|ом|у)?(?![а-яё])/giu,(word,end)=>{const result=({а:'рынка',е:'рынке',ом:'рынком',у:'рынку'})[(end||'').toLowerCase()]||'рынок';return word[0]===word[0].toUpperCase()?result[0].toUpperCase()+result.slice(1):result})};const dock=document.querySelector('#game-dock a[href="#market"] span');if(dock)dock.textContent='Рынок';const building=document.querySelector('.farm-market');if(building){building.querySelector('b').textContent='Рынок';const img=building.querySelector('img');if(img)img.src='art/market-building-v2.svg';building.setAttribute('aria-label','Рынок: купить и продать продукты')}}
farmViews.add(decorateMarketLanguage);
